<template>
  <div class="min-h-screen bg-gray-50">
    <header class="bg-white shadow-sm border-b">
      <div class="max-w-7xl mx-auto px-4 py-4 flex items-center justify-between">
        <h1 class="text-2xl font-bold text-gray-900">WebODM</h1>
        <div class="flex items-center gap-4">
          <Button variant="solid" theme="gray" @click="showNewProject = true">
            New Project
          </Button>
          <Avatar :label="user?.full_name?.charAt(0)" shape="circle" />
        </div>
      </div>
    </header>

    <main class="max-w-7xl mx-auto px-4 py-8">
      <div class="mb-6">
        <TextInput placeholder="Search projects..." v-model="search" />
      </div>

      <div v-if="loading" class="flex justify-center py-12">
        <Spinner />
      </div>

      <div v-else-if="projects.length === 0" class="text-center py-12">
        <h3 class="text-lg font-medium text-gray-600">No projects yet</h3>
        <p class="text-gray-400 mt-1">Create your first project to get started</p>
      </div>

      <div v-else class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        <Card v-for="project in projects" :key="project.name"
          :title="project.project_name"
          :subtitle="project.owner"
          @click="goToProject(project.name)"
          class="cursor-pointer hover:shadow-md transition-shadow"
        >
          <template #actions>
            <Badge v-for="tag in project.tags" :key="tag" theme="blue" size="sm">
              {{ tag }}
            </Badge>
          </template>
          <div class="text-sm text-gray-500 mt-2">
            {{ project.task_count || 0 }} tasks
          </div>
        </Card>
      </div>
    </main>

    <Dialog v-model="showNewProject" title="New Project">
      <template #body>
        <div class="space-y-4">
          <TextInput label="Name" v-model="newProjectName" placeholder="Project name" />
          <TextInput label="Description" v-model="newProjectDescription" placeholder="Project description" type="textarea" />
        </div>
      </template>
      <template #actions>
        <Button variant="solid" @click="createProject">Create</Button>
      </template>
    </Dialog>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { Button, Avatar, TextInput, Card, Badge, Spinner, Dialog } from 'frappe-ui'

const router = useRouter()
const projects = ref([])
const loading = ref(true)
const search = ref('')
const showNewProject = ref(false)
const newProjectName = ref('')
const newProjectDescription = ref('')
const user = ref(null)

async function fetchProjects() {
  try {
    const res = await fetch('/api/resource/WebODM%20Project')
    const data = await res.json()
    projects.value = data.data || []
  } catch (err) {
    console.error('Failed to fetch projects', err)
  } finally {
    loading.value = false
  }
}

async function createProject() {
  try {
    const res = await fetch('/api/resource/WebODM%20Project', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        project_name: newProjectName.value,
        description: newProjectDescription.value,
      }),
    })
    const data = await res.json()
    projects.value.push(data.data)
    showNewProject.value = false
    newProjectName.value = ''
    newProjectDescription.value = ''
  } catch (err) {
    console.error('Failed to create project', err)
  }
}

function goToProject(id) {
  router.push(`/project/${id}`)
}

async function fetchUser() {
  try {
    const res = await fetch('/api/method/frappe.auth.get_logged_user')
    const data = await res.json()
    user.value = data.message
  } catch (err) {
    console.error('Failed to fetch user', err)
  }
}

onMounted(() => {
  fetchProjects()
  fetchUser()
})
</script>
